package com.mohymods.kingdomsmp.profession;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
class ApiaryJobsEvidenceTest {
 @Test void explicitPurposeAndSupervisorAreExclusiveAndPersist(){var e=new ApiaryJobsEvidence();var site=new ApiaryEvidence.Site("minecraft:overworld",42);var p=UUID.randomUUID();var first=new ApiaryJobsEvidence.Job(p,ApiaryJobs.FOREST);var other=new ApiaryJobsEvidence.Job(UUID.randomUUID(),ApiaryJobs.REAGENTS);e.assign(site,first);e.record(site,first,"productivebees:iron",3);assertThrows(IllegalStateException.class,()->e.assign(site,other));var next=new ApiaryJobsEvidence.Job(p,ApiaryJobs.REAGENTS);e.assign(site,next);e.record(site,first,"productivebees:iron",3);e.record(site,next,"productivebees:copper",2);var restored=ApiaryJobsEvidence.load(e.save());assertEquals(Map.of("productivebees:iron",3),restored.counts(first));assertEquals(Map.of("productivebees:copper",2),restored.counts(next));restored.remove(site);restored.record(site,next,"productivebees:copper",10);assertEquals(2,restored.counts(next).get("productivebees:copper"));assertTrue(restored.at(site).isEmpty());}
 @Test void invalidSpeciesUnboundedOrMalformedCountsAndDuplicateSitesFailClosed(){var e=new ApiaryJobsEvidence();var site=new ApiaryEvidence.Site("minecraft:overworld",42);var job=new ApiaryJobsEvidence.Job(UUID.randomUUID(),ApiaryJobs.FOREST);e.assign(site,job);assertThrows(IllegalArgumentException.class,()->e.record(site,job,"productivebees:draconic",1));e.record(site,job,"productivebees:iron",4096);assertEquals(2304,e.counts(job).get("productivebees:iron"));var tag=e.save();var sites=tag.getList("jobs",Tag.TAG_COMPOUND);sites.add(sites.getCompound(0).copy());assertThrows(IllegalArgumentException.class,()->ApiaryJobsEvidence.load(tag));var wrong=e.save();wrong.getList("produced",Tag.TAG_COMPOUND).getCompound(0).getCompound("counts").putInt("productivebees:iron",2305);assertThrows(IllegalArgumentException.class,()->ApiaryJobsEvidence.load(wrong));}
 @Test void deliveryModelRequiresTwoForestSpeciesAndBoundsMixedReagents(){assertEquals(Map.of("productivebees:iron",16,"productivebees:copper",16),ApiaryInventory.totals(ApiaryJobs.FOREST,Map.of("productivebees:iron",16,"productivebees:copper",16)));assertThrows(IllegalArgumentException.class,()->ApiaryInventory.totals(ApiaryJobs.FOREST,Map.of("productivebees:iron",32)));assertEquals(Map.of("combs",16),ApiaryInventory.totals(ApiaryJobs.REAGENTS,Map.of("productivebees:iron",7,"productivebees:copper",9)));assertThrows(IllegalArgumentException.class,()->ApiaryInventory.totals(ApiaryJobs.REAGENTS,Map.of("productivebees:draconic",16)));}
 @Test void forestProductionBindsOnlyTheOriginalDocumentedInspectionBox(){String audit="minecraft:overworld@1024, 90, 1024;apiary=actualserverdigest;operator attestation";assertDoesNotThrow(()->ApiaryJobs.requireDocumentedSite(audit,"minecraft:overworld",new net.minecraft.core.BlockPos(1021,90,1024)));for(var pos:List.of(new net.minecraft.core.BlockPos(1033,90,1024),new net.minecraft.core.BlockPos(1024,94,1024)))assertThrows(IllegalStateException.class,()->ApiaryJobs.requireDocumentedSite(audit,"minecraft:overworld",pos));assertThrows(IllegalStateException.class,()->ApiaryJobs.requireDocumentedSite(audit,"minecraft:the_nether",new net.minecraft.core.BlockPos(1024,90,1024)));assertThrows(IllegalStateException.class,()->ApiaryJobs.requireDocumentedSite("unknown old site","minecraft:overworld",net.minecraft.core.BlockPos.ZERO));}

}
